package com.gameaggregator.deploymentservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.deploymentservice.api.DeploymentDtos.*;import com.gameaggregator.deploymentservice.domain.*;import com.gameaggregator.deploymentservice.infrastructure.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class DeploymentService{final DeploymentRepository deployments;final DeploymentEventRepository events;static final Map<DeploymentStatus,Set<DeploymentStatus>> ALLOWED=Map.of(DeploymentStatus.PENDING,Set.of(DeploymentStatus.QUEUED,DeploymentStatus.CANCELLED),DeploymentStatus.QUEUED,Set.of(DeploymentStatus.RUNNING,DeploymentStatus.CANCELLED),DeploymentStatus.RUNNING,Set.of(DeploymentStatus.SUCCEEDED,DeploymentStatus.FAILED,DeploymentStatus.CANCELLED),DeploymentStatus.SUCCEEDED,Set.of(DeploymentStatus.ROLLED_BACK),DeploymentStatus.FAILED,Set.of(DeploymentStatus.QUEUED,DeploymentStatus.ROLLED_BACK),DeploymentStatus.CANCELLED,Set.of(),DeploymentStatus.ROLLED_BACK,Set.of());public DeploymentService(DeploymentRepository d,DeploymentEventRepository e){deployments=d;events=e;}public Deployment create(Create r){var d=deployments.save(new Deployment(r.releaseId(),r.environmentId(),r.requestedBy()));events.save(new DeploymentEvent(d.id,DeploymentStatus.PENDING,DeploymentStatus.PENDING,r.requestedBy(),"Deployment created"));return d;}public List<Deployment> list(UUID releaseId){return releaseId==null?deployments.findAll():deployments.findAllByReleaseId(releaseId);}public Deployment get(UUID id){return deployments.findById(id).orElseThrow(()->new NotFoundException("DEPLOYMENT_NOT_FOUND","Deployment was not found"));}public Deployment transition(UUID id,Transition r){var d=get(id);var from=d.status;if(!ALLOWED.getOrDefault(from,Set.of()).contains(r.status()))throw new IllegalStateException("Invalid deployment transition: "+from+" -> "+r.status());d.status=r.status();if(r.status()==DeploymentStatus.RUNNING)d.startedAt=Instant.now();if(Set.of(DeploymentStatus.SUCCEEDED,DeploymentStatus.FAILED,DeploymentStatus.CANCELLED,DeploymentStatus.ROLLED_BACK).contains(r.status()))d.finishedAt=Instant.now();events.save(new DeploymentEvent(id,from,r.status(),r.actorId(),r.message()));return d;}public List<DeploymentEvent> events(UUID id){get(id);return events.findAllByDeploymentIdOrderByCreatedAtAsc(id);}}